import{_ as t,o,c as a,l as n,t as r,N as s}from"./chunks/framework.Gjrf2Eoj.js";const b=JSON.parse('{"title":"comm | x-cmd man (man1) | compare two sorted files line by line","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | comm - compare two sorted files line by line","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"comm | x-cmd man (man1) | compare two sorted files line by line"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | comm - compare two sorted files line by line"}]]},"headers":[],"params":{"isMan":true,"man":"comm","category":"man1","desc":"compare two sorted files line by line"},"relativePath":"man1/comm.md","filePath":"man1/comm.md"}'),i={name:"man1/comm.md"},l={class:"visually-hidden"},d=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>comm - compare two sorted files line by line</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>comm</strong> [<em>OPTION</em>]... <em>FILE1 FILE2</em></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Compare sorted files FILE1 and FILE2 line by line.</p><p>When FILE1 or FILE2 (not both) is -, read standard input.</p><p>With no options, produce three-column output. Column one contains lines unique to FILE1, column two contains lines unique to FILE2, and column three contains lines common to both files.</p><dl><dt><strong>-1</strong></dt><dd>suppress column 1 (lines unique to FILE1)</dd><dt><strong>-2</strong></dt><dd>suppress column 2 (lines unique to FILE2)</dd><dt><strong>-3</strong></dt><dd>suppress column 3 (lines that appear in both files)</dd><dt><strong>--check-order</strong></dt><dd>check that the input is correctly sorted, even if all input lines are pairable</dd><dt><strong>--nocheck-order</strong></dt><dd>do not check that the input is correctly sorted</dd><dt><strong>--output-delimiter</strong>=<em>STR</em></dt><dd>separate columns with STR</dd><dt><strong>--total</strong></dt><dd>output a summary</dd><dt><strong>-z</strong>, <strong>--zero-terminated</strong></dt><dd>line delimiter is NUL, not newline</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>Note, comparisons honor the rules specified by &#39;LC_COLLATE&#39;.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><dl><dt>comm -12 file1 file2</dt><dd>Print only lines present in both file1 and file2.</dd><dt>comm -3 file1 file2</dt><dd>Print lines in file1 not in file2, and vice versa.</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Richard M. Stallman and David MacKenzie.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>join</strong>(1), <strong>uniq</strong>(1)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/comm%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/comm\\</a>&gt; <br> or available locally via: info &#39;(coreutils) comm invocation&#39;</p>',21);function c(e,m,p,h,u,g){return o(),a("div",null,[n("h1",l,r(e.$params.man),1),d])}const _=t(i,[["render",c]]);export{b as __pageData,_ as default};
